from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)
    best_vector = None
    best_versions = None

    initial_requirements = {}
    for name, bounds in roots.items():
        initial_requirements.setdefault(name, []).append(tuple(bounds))

    def active_dependencies(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature")
            if feature and feature not in features:
                continue
            yield dep

    def is_acyclic(versions, assigned):
        graph = {name: [] for name in versions}
        for name in versions:
            row = assigned[name]
            for dep in active_dependencies(row):
                target = dep["name"]
                if target not in versions:
                    return False
                graph[name].append(target)
        visiting = set()
        visited = set()

        def visit(node):
            if node in visiting:
                return False
            if node in visited:
                return True
            visiting.add(node)
            for target in graph[node]:
                if not visit(target):
                    return False
            visiting.remove(node)
            visited.add(node)
            return True

        return all(visit(node) for node in graph)

    def search(assigned, requirements, expanded):
        nonlocal best_vector, best_versions
        requirements = {name: list(ranges) for name, ranges in requirements.items()}
        expanded = set(expanded)

        # Expand dependency constraints for every selected version.
        changed = True
        while changed:
            changed = False
            for name, row in list(assigned.items()):
                if name in expanded:
                    continue
                expanded.add(name)
                changed = True
                for dep in active_dependencies(row):
                    requirements.setdefault(dep["name"], []).append(
                        (dep["min"], dep["max"])
                    )

        for name, row in assigned.items():
            version = row["version"]
            if any(not lo <= version <= hi for lo, hi in requirements.get(name, [])):
                return
            if version in blocked.get(name, []):
                return
            if name in pins and version != pins[name]:
                return

        domains = {}
        for name in requirements:
            if name in assigned:
                continue
            candidates = []
            for row in packages.get(name, []):
                version = row["version"]
                if any(not lo <= version <= hi for lo, hi in requirements[name]):
                    continue
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                candidates.append(row)
            if not candidates:
                return
            domains[name] = candidates

        # An admissible lexicographic upper bound lets us discard inferior branches.
        if best_vector is not None:
            upper = []
            for name in names:
                if name in assigned:
                    upper.append(assigned[name]["version"])
                elif name in domains:
                    upper.append(max(row["version"] for row in domains[name]))
                else:
                    rows = packages.get(name, [])
                    upper.append(max((row["version"] for row in rows), default=-1))
            if tuple(upper) <= best_vector:
                return

        if not domains:
            versions = {name: row["version"] for name, row in assigned.items()}
            if not is_acyclic(versions, assigned):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = versions
            return

        name = min(domains, key=lambda n: (len(domains[n]), n))
        for row in sorted(domains[name], key=lambda r: r["version"], reverse=True):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            search(next_assigned, requirements, expanded)

    search({}, initial_requirements, set())
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
